import { ALLERGENS, type Allergen, type Product } from '../contract.ts';
import { detectAllergens } from '../allergens/index.ts';
import { hasNonNutritiveSweetener } from '../score/sweeteners.ts';
import type { AvoidKey, Profile } from './types.ts';

export type MatchableProduct = Pick<Product, 'ingredientsText' | 'allergens' | 'mayContain'> & {
  ingredients: { name: string; slug?: string | null }[];
  processing?: { level: number } | null;
};
